# Find connected components of 0s (orthogonal connectivity)
def find_zero_components(grid):
    height, width = len(grid), len(grid[0])
    visited = set()
    zero_components = []

    for i in range(height):
        for j in range(width):
            if grid[i][j] == 0 and (i,j) not in visited:
                component = set()
                queue = deque([(i,j)])
                visited.add((i,j))
                while queue:
                    ci, cj = queue.popleft()
                    component.add((ci,cj))
                    for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < height and 0 <= nj < width and grid[ni][nj] == 0 and (ni,nj) not in visited:
                            visited.add((ni,nj))
                            queue.append((ni,nj))
                zero_components.append(component)

    return zero_components

