# Manually trace paths between specific cells to verify connectivity
def can_reach(a_pos, b_pos, grid):
    """Check if two positions are connected via orthogonal path of non-zero"""
    qi,qj = a_pos
    ti,tj = b_pos

    visited = set()
    queue = deque([(qi,qj)])
    visited.add((qi,qj))

    while queue:
        ci,cj = queue.popleft()
        if ci == ti and cj == tj:
            return True
        for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni,nj = ci+di, cj+dj
            if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                if grid[ni][nj] != 0 and (ni,nj) not in visited:
                    visited.add((ni,nj))
                    queue.append((ni,nj))
    return False

# Check all pairs in what I think is the target component
cells_to_check = [(1,3), (1,4), (2,3), (2,4), (2,5), (3,3), (3,4), (4,4), (4,5)]

print("Verifying connectivity between cells:")
for i, c1 in enumerate(cells_to_check):
    for j, c2 in enumerate(cells_to_check):
        if i < j:
            reachable = can_reach(c1, c2, demo_in)
